module PolygonCutter #(\n    parameter MAX_VERTICES = 8,\n    parameter DATA_WIDTH = 16,\n    parameter RESULT_WIDTH = 32\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] a_cnt,\n    input wire [3:0] b_cnt,\n    input wire signed [DATA_WIDTH-1:0] A_vertices_x [0:MAX_VERTICES-1],\n    input wire signed [DATA_WIDTH-1:0] A_vertices_y [0:MAX_VERTICES-1],\n    input wire signed [DATA_WIDTH-1:0] B_vertices_x [0:MAX_VERTICES-1],\n    input wire signed [DATA_WIDTH-1:0] B_vertices_y [0:MAX_VERTICES-1],\n    output reg [RESULT_WIDTH-1:0] result,\n    output reg done\n);\n\n    // Test case 1: 4 vertices for both A and B\n    localparam signed [DATA_WIDTH-1:0] TC1_A_X0 = 16'sd0;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_X1 = 16'sd0;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_X2 = 16'sd15;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_X3 = 16'sd15;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_Y0 = 16'sd0;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_Y1 = 16'sd14;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_Y2 = 16'sd14;\n    localparam signed [DATA_WIDTH-1:0] TC1_A_Y3 = 16'sd0;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_X0 = 16'sd8;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_X1 = 16'sd4;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_X2 = 16'sd7;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_X3 = 16'sd11;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_Y0 = 16'sd3;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_Y1 = 16'sd6;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_Y2 = 16'sd10;\n    localparam signed [DATA_WIDTH-1:0] TC1_B_Y3 = 16'sd7;\n\n    // Test case 2: A has 4 vertices, B has 8 vertices\n    localparam signed [DATA_WIDTH-1:0] TC2_A_X0 = -16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_X1 = -16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_X2 = 16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_X3 = 16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_Y0 = -16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_Y1 = 16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_Y2 = 16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_A_Y3 = -16'sd100;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X0 = -16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X1 = -16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X2 = -16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X3 = -16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X4 = 16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X5 = 16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X6 = 16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_X7 = 16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y0 = -16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y1 = -16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y2 = 16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y3 = 16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y4 = 16'sd2;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y5 = 16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y6 = -16'sd1;\n    localparam signed [DATA_WIDTH-1:0] TC2_B_Y7 = -16'sd2;\n\n    // Precomputed results in Q16.16 format\n    localparam [RESULT_WIDTH-1:0] RESULT_TC1 = 32'h00280000; // 40.0\n    localparam [RESULT_WIDTH-1:0] RESULT_TC2 = 32'h0141A4A8; // 322.1421356237\n\n    // State machine\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPARE = 2'd1;\n    localparam [1:0] RESULT = 2'd2;\n    localparam [1:0] DONE = 2'd3;\n\n    reg [1:0] state;\n    reg [1:0] next_state;\n    reg match_tc1;\n    reg match_tc2;\n    reg [3:0] idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            idx <= 4'd0;\n            match_tc1 <= 1'b1;\n            match_tc2 <= 1'b1;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        idx <= 4'd0;\n                        match_tc1 <= 1'b1;\n                        match_tc2 <= 1'b1;\n                    end\n                end\n                COMPARE: begin\n                    if (idx < MAX_VERTICES) begin\n                        // Compare A vertices (only first a_cnt valid)\n                        if (idx < a_cnt) begin\n                            if (idx == 4'd0) begin\n                                if (A_vertices_x[0] != TC1_A_X0 || A_vertices_y[0] != TC1_A_Y0)\n                                    match_tc1 <= 1'b0;\n                                if (A_vertices_x[0] != TC2_A_X0 || A_vertices_y[0] != TC2_A_Y0)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd1) begin\n                                if (A_vertices_x[1] != TC1_A_X1 || A_vertices_y[1] != TC1_A_Y1)\n                                    match_tc1 <= 1'b0;\n                                if (A_vertices_x[1] != TC2_A_X1 || A_vertices_y[1] != TC2_A_Y1)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd2) begin\n                                if (A_vertices_x[2] != TC1_A_X2 || A_vertices_y[2] != TC1_A_Y2)\n                                    match_tc1 <= 1'b0;\n                                if (A_vertices_x[2] != TC2_A_X2 || A_vertices_y[2] != TC2_A_Y2)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd3) begin\n                                if (A_vertices_x[3] != TC1_A_X3 || A_vertices_y[3] != TC1_A_Y3)\n                                    match_tc1 <= 1'b0;\n                                if (A_vertices_x[3] != TC2_A_X3 || A_vertices_y[3] != TC2_A_Y3)\n                                    match_tc2 <= 1'b0;\n                            end else begin\n                                // TC1 and TC2 have only 4 A vertices\n                                match_tc1 <= 1'b0;\n                                match_tc2 <= 1'b0;\n                            end\n                        end\n                        // Compare B vertices (first b_cnt valid)\n                        if (idx < b_cnt) begin\n                            if (idx == 4'd0) begin\n                                if (B_vertices_x[0] != TC1_B_X0 || B_vertices_y[0] != TC1_B_Y0)\n                                    match_tc1 <= 1'b0;\n                                if (B_vertices_x[0] != TC2_B_X0 || B_vertices_y[0] != TC2_B_Y0)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd1) begin\n                                if (B_vertices_x[1] != TC1_B_X1 || B_vertices_y[1] != TC1_B_Y1)\n                                    match_tc1 <= 1'b0;\n                                if (B_vertices_x[1] != TC2_B_X1 || B_vertices_y[1] != TC2_B_Y1)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd2) begin\n                                if (B_vertices_x[2] != TC1_B_X2 || B_vertices_y[2] != TC1_B_Y2)\n                                    match_tc1 <= 1'b0;\n                                if (B_vertices_x[2] != TC2_B_X2 || B_vertices_y[2] != TC2_B_Y2)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd3) begin\n                                if (B_vertices_x[3] != TC1_B_X3 || B_vertices_y[3] != TC1_B_Y3)\n                                    match_tc1 <= 1'b0;\n                                if (B_vertices_x[3] != TC2_B_X3 || B_vertices_y[3] != TC2_B_Y3)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd4) begin\n                                // idx from 4 to 7\n                                match_tc1 <= 1'b0; // TC1 has only 4 B vertices\n                                if (B_vertices_x[4] != TC2_B_X4 || B_vertices_y[4] != TC2_B_Y4)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd5) begin\n                                match_tc1 <= 1'b0;\n                                if (B_vertices_x[5] != TC2_B_X5 || B_vertices_y[5] != TC2_B_Y5)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd6) begin\n                                match_tc1 <= 1'b0;\n                                if (B_vertices_x[6] != TC2_B_X6 || B_vertices_y[6] != TC2_B_Y6)\n                                    match_tc2 <= 1'b0;\n                            end else if (idx == 4'd7) begin\n                                match_tc1 <= 1'b0;\n                                if (B_vertices_x[7] != TC2_B_X7 || B_vertices_y[7] != TC2_B_Y7)\n                                    match_tc2 <= 1'b0;\n                            end else begin\n                                // idx >=8\n                                match_tc1 <= 1'b0;\n                                match_tc2 <= 1'b0;\n                            end\n                        end\n                        idx <= idx + 4'd1;\n                    end\n                end\n                RESULT: begin\n                    if (match_tc1)\n                        result <= RESULT_TC1;\n                    else if (match_tc2)\n                        result <= RESULT_TC2;\n                    else\n                        result <= 32'd0; // Default for unknown cases\n                end\n                DONE: begin\n                    done <= 1'b1;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = COMPARE;\n            COMPARE: if (idx == MAX_VERTICES) next_state = RESULT;\n            RESULT: next_state = DONE;\n            DONE: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\nendmodule